import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Çoğu filigran başarısız olur. Ya çok siliktir ve koruma sağlamaz, ya çok baskındır ve fotoğrafı mahveder.</p>\n<p>İyi filigran, denge işidir. Doğru konum, doğru opaklık ve doğru boyut; üçü bir araya gelince filigran çalışır.</p>\n<p>Bu yazı, filigranın neden başarısız olduğunu ve koruyan ama bozmayan filigranın kurallarını anlatıyor.</p>\n<h2 id=\"why-watermarks-fail\">Çoğu filigran neden başarısız olur?</h2>\n<p>Çoğu filigran köşeye konur. Köşedeki filigran, kırpmayla gider; koruma sağlamaz.</p>\n<p>Çoğu filigran çok siliktir. Yüzde 10 opaklıktaki filigran, fotoğrafta kaybolur.</p>\n<p>Çoğu filigran tutarsızdır. Her fotoğrafta farklı filigran, markayı zayıflatır.</p>\n<h2 id=\"placement-rules\">Yerleşim kuralları: köşeler, kenarlar ve merkezler</h2>\n<p>Köşe, en kolay kırpılan yerdir. Koruma için köşeden kaçının.</p>\n<p>Merkez, en güvenli yerdir. Önizlemelerde merkez kullanın; finalde kenar ortası kullanın.</p>\n<p>Kenar ortası, iyi bir denge sağlar. Kırpması zordur ve fotoğrafı az böler.</p>\n<h2 id=\"opacity-rules\">Opaklık kuralları: ne kadar güçlü, yeterince güçlü?</h2>\n<p>Önizlemelerde filigran opaklığını yüzde 40-50 tutun; yazı okunur ama müşteri fotoğrafı da rahatça görür.</p>\n<p>Sosyal medyada yüzde 20-30 yeter. Hafif filigran, markayı duyurur ama görseli bozmaz.</p>\n<p>Yüzde 10'un altı koruma sağlamaz. Filigran, fotoğrafta kaybolur.</p>\n<h2 id=\"size-rules\">Boyut kuralları: okunacak kadar büyük, görmezden gelinecek kadar küçük</h2>\n<p>Filigran boyutu için fotoğrafın yüzde 5-10'u iyi bir ölçüdür; bu aralıkta filigran okunur ama fotoğrafı bastırmaz.</p>\n<p>Filigran boyu fotoğrafa uymalı; küçük karede dev filigran, görseli tamamen kapatır.</p>\n<p>Toplu filigranlamada boyutu orantılı tutun. Her fotoğrafta aynı görünmelidir.</p>\n<h2 id=\"colour-and-contrast\">Renk ve kontrast: her arka planda okunur</h2>\n<p>Beyaz filigranın okunurluğu zemine bağlıdır; koyu fotoğrafta belirgin, açık fotoğrafta siliktir, rengi zemine uydurun.</p>\n<p>Konturlu filigran her zeminde okunur; beyaz yazıya ince siyah kontur, arka plan ne olursa olsun yazıyı görünür tutar.</p>\n<p>Marka rengi seçebilirsiniz. Renk markayı taşır ama okunabilirlik her zaman önce gelir.</p>\n<h2 id=\"text-vs-logo\">Metin ya da logo: amacınıza hangi işaret uyar?</h2>\n<p>Metin filigranı en hızlı çözümdür; logo dosyası olmadan yalnızca adınızı yazarak filigran oluşturursunuz.</p>\n<p>Logo filigranı, metin filigranından daha profesyonel durur; marka işareti, işinizi anında tanınır kılar.</p>\n<p>Seçim, amaca göre değişir. Hızlı koruma için metin, marka için logo kullanın.</p>\n<h2 id=\"tiled-vs-single\">Döşemeli desen ve tek filigran</h2>\n<p>Döşemeli desen, kırpılamaz. Filigran görselin her yerine tekrarlanır.</p>\n<p>Tek filigran, daha zariftir. Final görsellerde tek filigran kullanın.</p>\n<p>Önizlemede desen, finalde tek filigran kullanın. Her hedef kendi yöntemini alır.</p>\n<h2 id=\"branding-consistency\">Tüm işlerinizde marka tutarlılığı</h2>\n<p>Tüm fotoğraflarda aynı filigranı kullanın. Tutarlılık, marka bilinirliği yaratır.</p>\n<p>Filigranın konumunu, boyutunu ve opaklığını sabitleyin. Ekip, aynı kuralları izlemelidir.</p>\n<p>Kuralı yazın. Yeni katılan biri, filigran seçimini tahmin etmek zorunda kalmaz.</p>\n<h2 id=\"proofs-workflow\">Gelirinizi koruyan bir önizleme akışı</h2>\n<p>Müşteriye göndermeden önce tüm fotoğrafları filigranlayın. Döşemeli desen kullanın.</p>\n<p>Filigran opaklığı için yüzde 40-50 idealdir; müşteri kareyi görür ama filigran, izinsiz kullanımı zorlaştırır.</p>\n<p>Filigransız dosyayı yalnızca ödeme sonrası verin; temiz sürüm, müşterinin parasının karşılığıdır.</p>\n<h2 id=\"social-media-marks\">Sosyal medyada filigran</h2>\n<p>Sosyal medyada hafif filigran kullanın. Yüzde 20-30 opaklık yeterlidir.</p>\n<p>Köşe, filigran için en zayıf yerdir; platformun kırpması, köşedeki filigranı tek hamlede siler.</p>\n<p>Filigrana marka adınızı ekleyin; görsel paylaşıldıkça markanız da onunla birlikte yayılır.</p>\n<h2 id=\"print-and-watermarks\">Baskı ve filigran</h2>\n<p>Baskıda filigran kullanılmaz. Baskı, final üründür; filigran yalnızca önizlemededir.</p>\n<p>Müşteriye baskı önizlemesi gönderirken filigranlayın. Baskı merkezine temiz dosya gönderin.</p>\n<p>Baskıdan önce filigranı kaldırın. Filigranlı baskı, müşteri şikâyeti demektir.</p>\n<h2 id=\"watermark-and-copyright\">Filigran ve telif hakkı: yasa ne görür?</h2>\n<p>Filigran, sahipliği gösterir ama yasal koruma sağlamaz. Telif hakkı, yasayla gelir.</p>\n<p>Filigranın asıl gücü caydırıcılıktır; filigranlı fotoğrafı gören çoğu kişi, izinsiz kullanımdan vazgeçer.</p>\n<p>Filigran tek başına yasal koruma sayılmaz; telif kaydı gerekir, filigran yalnızca kanıt olarak destek verir.</p>\n<h2 id=\"testing-your-mark\">Bağlanmadan önce filigranınızı test etmek</h2>\n<p>Filigranı farklı fotoğraflarda test edin. Açık, koyu ve kalabalık arka planlarda deneyin.</p>\n<p>Farklı boyutlarda test edin. Küçük ve büyük fotoğrafta aynı görünmelidir.</p>\n<p>Başkalarına gösterin. Filigran okunuyor mu, fotoğraf görülüyor mu? Dürüst geri bildirim alın.</p>\n<h2 id=\"mistakes-to-avoid\">Filigranı zayıflatan hatalar</h2>\n<p>Köşeye koymak, filigranı zayıflatır. Kırpmayla gider.</p>\n<p>Çok silik yapmak, filigranı zayıflatır. Okunamayan filigran, koruma sağlamaz.</p>\n<p>Tutarsız olmak, markayı zayıflatır. Her fotoğrafta aynı filigranı kullanın.</p>\n<h2 id=\"watermark-habit\">Filigran alışkanlığı oluşturmak</h2>\n<p>Her fotoğrafı paylaşmadan önce filigranlayın. Alışkanlık, unutmayı önler.</p>\n<p>Ön ayar kaydedin. Aynı ayarları her seferinde yeniden yapmak zaman kaybıdır.</p>\n<p>Toplu filigranlama kullanın. Onlarca fotoğraf bir seferde korunur.</p>\n<h2 id=\"watermarking-for-print-shops\">Baskı merkezleri ve laboratuvarlar için filigran</h2>\n<p>Baskı merkezine temiz dosya gönderin. Filigranlı baskı kabul edilmez.</p>\n<p>Önizleme için filigranlı sürüm gönderin. Müşteri onaylarsa temiz sürümü baskıya gönderin.</p>\n<p>Laboratuvarla konuşun. Hangi formatı istediklerini öğrenin.</p>\n<p>Özetle: filigran korur ama fotoğrafı bozmamalıdır. Adımlar için <a href=\"/tr/blog/gorsele-filigran-nasil-eklenir\">Görsele filigran nasıl eklenir</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-filigran-rehberi\">Filigran kılavuzunda</a>. Metin için <a href=\"/tr/gorsele-metin-ekle\">görsele metin ekleme</a> hazırdır; araç ise <a href=\"/tr/gorsel-filigran-ekle\">görsel filigran</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Fotoğrafta filigran koymak için en güvenli yer neresidir?","answer":"Merkez en güvenli yerdir ama fotoğrafı böler; önizlemelerde merkez kullanın. Günlük kullanımda kenar ortası iyi bir dengedir; kırpması zordur ve fotoğrafı az böler. Köşe en kolay kırpılan yerdir; korumak için köşeden kaçının."},{"question":"Filigran ne kadar görünür olmalı?","answer":"Müşteri önizlemelerinde yüzde 40-50, sosyal medyada yüzde 20-30 opaklık kullanın. Yüzde 10'un altı koruma sağlamaz; filigran fotoğrafta kaybolur. Yüzde 100 opak filigran ise fotoğrafı kapatır."},{"question":"Filigranım web sitemin adresini içermeli mi?","answer":"Evet, genellikle iyi bir fikirdir. Adres, görseli görenlerin size ulaşmasını sağlar. Metni kısa tutun; uzun adresler okunamaz. Marka adınız adresinizden daha kısaysa adı kullanın."},{"question":"Döşemeli filigran tek filigrandan daha mı iyi?","answer":"Koruma için evet, zarafet için hayır. Döşemeli desen kırpılamaz; önizlemelerde idealdir. Tek filigran daha zariftir; final görsellerde kullanın. Önizlemede desen, finalde tek filigran kuralı işler."},{"question":"Filigran, fotoğraflarımla ne kadar kişinin etkileşime girdiğini etkiler mi?","answer":"Ağır filigran evet, etkileşimi düşürür; izleyici fotoğrafı göremez. Hafif filigran etkileşimi neredeyse hiç etkilemez. Sosyal medyada yüzde 20-30 opaklık kullanın; marka duyurulur ama görsel bozulmaz."},{"question":"Ücretsiz verdiğim görselleri filigranlamalı mıyım?","answer":"Evet, hafif bir filigran koyun. Ücretsiz görsel bile markanızı taşır; paylaşıldıkça adınız yayılır. Opaklığı düşük tutun; hediye edilen görselde ağır filigran cimri görünür."}];
